mapper.select:
select segm_id as segmId, parent_segm_id as parentSegmId, segm_name as segmName, stand_name as standName, segm_no as segmNo, stand_no as standNo, segm_type as segmType, region_id as regionId, district_id as districtId, service_region_id as serviceRegionId, station_id as stationId, installstation_id as installStationId, busstation_id as busStationId, status as status, notes as notes, create_date as createDate from ADDR_SEGM
and ifnull(delete_state, '0') = '0'
and segm_id = #{bo.segmId}
and parent_segm_id = #{bo.parentSegmId}
and segm_name like concat('%', #{bo.segmName}, '%')
and stand_name like concat('%', #{bo.standName}, '%')
and status = #{bo.status}
and segm_type in
#{segmType}
order by create_date desc
